#!/usr/bin/env python3
"""Generate native/Kotlin effect parameter IDs and ranges from one source."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
s=json.loads((root/'tools/fx-schema.json').read_text());params=s['parameters']
assert next(p[3] for p in params if p[0]=='ScSource')==json.loads((root/'tools/capacity-schema.json').read_text())['tracks']-1
def f(v):return f'{float(v):.9g}'+('.0' if float(v).is_integer() else '')+'f'
h=['// Generated by tools/generate_fx_schema.py.', '#pragma once','#include <array>','namespace astra::fx {','enum Param : int {']
h += [f'    {p[0]} = {i},' for i,p in enumerate(params)]
h += [f'    ParameterCount = {len(params)}','};','struct Spec { float low, high, initial; bool integer; };','inline constexpr std::array<Spec, ParameterCount> specs{{']
h += ['    {'+', '.join([f(p[2]),f(p[3]),f(p[4]),str(p[5]).lower()])+'},' for p in params]
h += ['}};','inline constexpr std::array<const char*, 4> presetNames{{'+','.join(json.dumps(x) for x in s['presets'])+'}};','}','']
(root/'app/src/main/cpp/fx/FxIds.h').write_text('\n'.join(h))
k=['// Generated by tools/generate_fx_schema.py.','package com.weskestis.astrastudio.fx','','data class FxParamInfo(val name: String, val minimum: Float, val maximum: Float, val initial: Float, val integer: Boolean, val logarithmic: Boolean)','object FxSchema {']
k += [f'    const val {p[0]} = {i}' for i,p in enumerate(params)]
k += [f'    const val PARAM_COUNT = {len(params)}','    const val WIRE_COUNT = PARAM_COUNT + 8 + 8 + 12','    val parameters = listOf(']
k += [f'        FxParamInfo({json.dumps(p[1])}, {f(p[2])}, {f(p[3])}, {f(p[4])}, {str(p[5]).lower()}, {str(p[6]).lower()}),' for p in params]
k += ['    )','    val keys = listOf('+','.join(json.dumps(p[0]) for p in params)+')','    val presets = listOf('+','.join(json.dumps(x) for x in s['presets'])+')','    val units = listOf("EQ Eight", "Multiband / OTT", "Saturator", "Sidechain", "Ping-pong delay", "Reverb", "Chorus / Ensemble", "Phaser / Flanger")','}','']
(root/'app/src/main/java/com/weskestis/astrastudio/fx/FxSchema.kt').write_text('\n'.join(k))
